import ast
import os
import sys
import subprocess
import tempfile
import shutil
import time
import json
import re
import tomllib
import inspect
import unittest
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency on artifacts.py (assumed to be available in the same package or importable)
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        filter_bundle,
        partition_bundle,
        count_source_files
    )
except ImportError:
    # Fallback definitions if artifacts.py is not yet available or importable
    # These mirror the specification provided for artifacts.py
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts[:-1]: # Check directory segments
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        while path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle.keys():
            if any(path.endswith(s) for s in suffixes):
                count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = len([g for g in evaluated if g.passed])
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append(f"Pass Rate: {self.pass_rate:.2%}")
        lines.append("Gates:")
        for g in self.gates:
            lines.append(f"  [{g.status.upper():7}] {g.name:10} ({g.method}): {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename hint
    # Pattern: ```[language] [filename]\n...\n```
    # We look for blocks that might contain a filename in the info string or just assume sequential naming if not found.
    # However, the spec implies recovering a path->content map. 
    # Common convention in these deliverables is ```python path/to/file.py
    pattern = r'```(?:\w+)?\s+([^\n]+)\n(.*?)```'
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for i, (path_hint, content) in enumerate(matches):
        # Clean up path hint
        path = path_hint.strip()
        # If the path hint looks like a filename, use it. Otherwise, generate a name.
        if not path or path.startswith('#') or ' ' in path and not path.endswith('.py'):
             # Heuristic: if it doesn't look like a path, maybe it's just a language tag or garbage
             # Try to find a .py extension in the hint
             if '.py' in path:
                 path = path.split('.py')[0] + '.py'
             else:
                 path = f"extracted_block_{i}.py"

        # Sanitize the path using artifacts logic if available
        try:
            path = sanitize_path(path)
        except:
            pass

        if path:
            bundle[path] = content

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict-like
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace_dict'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace_attr'

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(authored_bundle)
        python_files = count_source_files(authored_bundle, suffixes=('.py',))

        if authored_files == 0:
            # Empty workspace
            gates = [
                GateResult(name='syntax', status=FAILED, method='ast_parse', detail='No authored files found'),
                GateResult(name='build', status=FAILED, method='metadata_check', detail='No authored files found'),
                GateResult(name='smoke', status=FAILED, method='import_check', detail='No authored files found'),
                GateResult(name='tests', status=FAILED, method='test_run', detail='No authored files found'),
                GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No authored files found'),
            ]
            failed_count = sum(1 for g in gates if g.status == FAILED)
            return VerificationReport(
                gates=gates,
                score_penalty=failed_count * self.penalty_per_gate,
                authored_files=0,
                python_files=0,
                source=source
            )

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write bundle to disk
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out generated dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = count_source_files(authored, suffixes=('.py',))

        gates = []

        # 1. Syntax Gate
        start_time = time.time()
        syntax_status = PASSED
        syntax_detail = ''
        syntax_method = 'ast_parse'
        syntax_evidence = {}

        py_files = [p for p in authored.keys() if p.endswith('.py')]
        if not py_files:
            syntax_status = FAILED
            syntax_detail = 'No Python files found'
        else:
            errors = []
            for p in py_files:
                try:
                    ast.parse(authored[p])
                except SyntaxError as e:
                    errors.append(f"{p}: {e}")
            if errors:
                syntax_status = FAILED
                syntax_detail = "Syntax errors: " + "; ".join(errors)
            else:
                syntax_detail = f"Parsed {len(py_files)} Python files successfully"

        gates.append(GateResult(
            name='syntax',
            status=syntax_status,
            method=syntax_method,
            detail=syntax_detail,
            duration_s=time.time() - start_time,
            evidence=syntax_evidence
        ))

        # 2. Build Gate
        start_time = time.time()
        build_status = PASSED
        build_detail = ''
        build_method = 'metadata_check'
        build_evidence = {}

        # Check for packaging metadata
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None
        for mf in metadata_files:
            if mf in authored:
                found_metadata = mf
                break

        if not found_metadata:
            build_status = FAILED
            build_detail = 'No packaging metadata (pyproject.toml, setup.py, setup.cfg) found'
        else:
            if found_metadata == 'pyproject.toml':
                try:
                    with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                        data = tomllib.load(f)
                    # Check for required tables
                    if not any(k in data for k in ['project', 'build-system', 'tool']):
                        build_status = FAILED
                        build_detail = 'pyproject.toml missing [project], [build-system], or [tool]'
                    else:
                        build_detail = 'pyproject.toml valid'
                except Exception as e:
                    build_status = FAILED
                    build_detail = f'pyproject.toml invalid: {e}'
            else:
                build_detail = f'{found_metadata} found'

            # Attempt pip install if pyproject.toml is present and valid so far
            if build_status == PASSED and found_metadata == 'pyproject.toml':
                try:
                    # Check if pip is available
                    subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                                   capture_output=True, timeout=10, check=True)
                    # Run install
                    cmd = [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
                    res = subprocess.run(cmd, cwd=workdir, capture_output=True, text=True, timeout=self.timeout_s)
                    if res.returncode != 0:
                        build_status = FAILED
                        build_detail += f"; pip install failed: {res.stderr}"
                    else:
                        build_detail += "; pip install succeeded"
                except FileNotFoundError:
                    build_status = SKIPPED
                    build_detail += "; pip not available"
                except subprocess.TimeoutExpired:
                    build_status = FAILED
                    build_detail += "; pip install timed out"
                except Exception as e:
                    build_status = FAILED
                    build_detail += f"; pip install error: {e}"

        gates.append(GateResult(
            name='build',
            status=build_status,
            method=build_method,
            detail=build_detail,
            duration_s=time.time() - start_time,
            evidence=build_evidence
        ))

        # 3. Smoke Gate
        start_time = time.time()
        smoke_status = PASSED
        smoke_detail = ''
        smoke_method = 'import_check'
        smoke_evidence = {}

        # Identify non-test modules
        # Exclude test files (basename contains 'test')
        non_test_modules = []
        for p in py_files:
            basename = os.path.basename(p).lower()
            if 'test' not in basename:
                non_test_modules.append(p)

        if not non_test_modules:
            smoke_status = FAILED
            smoke_detail = 'No non-test modules found'
        else:
            # Prepare PYTHONPATH
            env = os.environ.copy()
            python_path = [workdir, os.path.join(workdir, 'src')]
            if 'PYTHONPATH' in env:
                python_path.append(env['PYTHONPATH'])
            env['PYTHONPATH'] = os.pathsep.join(python_path)

            import_errors = []
            module_not_found_errors = []

            for mod_path in non_test_modules:
                # Convert path to module name
                # e.g., src/foo/bar.py -> foo.bar
                rel_path = os.path.relpath(mod_path, workdir)
                if rel_path.startswith('src/'):
                    rel_path = rel_path[4:]
                mod_name = rel_path.replace('/', '.').replace('\\', '.').replace('.py', '')

                # Run import in subprocess
                code = f"import {mod_name}"
                try:
                    res = subprocess.run(
                        [self.python_executable, '-c', code],
                        env=env,
                        capture_output=True,
                        text=True,
                        timeout=self.timeout_s
                    )
                    if res.returncode != 0:
                        stderr = res.stderr
                        if 'ModuleNotFoundError' in stderr:
                            # Check if it's a third-party package (not part of the bundle)
                            # Simple heuristic: if the missing module is not in our bundle paths
                            # Extract missing module name
                            match = re.search(r"No module named '([^']+)'", stderr)
                            if match:
                                missing_mod = match.group(1)
                                # Check if missing_mod corresponds to any file in bundle
                                # This is tricky because of package structures. 
                                # If the missing module is not a prefix of any authored .py file, it's likely third-party.
                                is_internal = False
                                for p in py_files:
                                    # Normalize path to module name
                                    rel = os.path.relpath(p, workdir)
                                    if rel.startswith('src/'): rel = rel[4:]
                                    m = rel.replace('/', '.').replace('\\', '.').replace('.py', '')
                                    if m == missing_mod or m.startswith(missing_mod + '.') or missing_mod.startswith(m + '.'):
                                        is_internal = True
                                        break
                                if not is_internal:
                                    module_not_found_errors.append(f"{mod_name}: {missing_mod}")
                                else:
                                    import_errors.append(f"{mod_name}: {stderr}")
                            else:
                                import_errors.append(f"{mod_name}: {stderr}")
                        else:
                            import_errors.append(f"{mod_name}: {stderr}")
                except subprocess.TimeoutExpired:
                    import_errors.append(f"{mod_name}: Timeout")
                except Exception as e:
                    import_errors.append(f"{mod_name}: {e}")

            if import_errors:
                smoke_status = FAILED
                smoke_detail = 'Import errors: ' + '; '.join(import_errors)
            elif module_not_found_errors:
                smoke_status = SKIPPED
                smoke_detail = 'Skipped due to missing third-party packages: ' + '; '.join(module_not_found_errors)
            else:
                smoke_detail = f'Imported {len(non_test_modules)} modules successfully'

        gates.append(GateResult(
            name='smoke',
            status=smoke_status,
            method=smoke_method,
            detail=smoke_detail,
            duration_s=time.time() - start_time,
            evidence=smoke_evidence
        ))

        # 4. Tests Gate
        start_time = time.time()
        tests_status = PASSED
        tests_detail = ''
        tests_method = 'test_run'
        tests_evidence = {}

        # Discover test files
        test_files = [p for p in py_files if 'test' in os.path.basename(p).lower()]

        if not test_files:
            tests_status = FAILED
            tests_detail = 'No test files found'
        else:
            # Prepare PYTHONPATH
            env = os.environ.copy()
            python_path = [workdir, os.path.join(workdir, 'src')]
            if 'PYTHONPATH' in env:
                python_path.append(env['PYTHONPATH'])
            env['PYTHONPATH'] = os.pathsep.join(python_path)

            # Check if pytest is available
            pytest_available = False
            try:
                subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                               capture_output=True, timeout=10, check=True)
                pytest_available = True
            except Exception:
                pytest_available = False

            if pytest_available:
                # Run pytest
                cmd = [self.python_executable, '-m', 'pytest', '-v'] + test_files
                try:
                    res = subprocess.run(cmd, cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)
                    if res.returncode == 0:
                        tests_detail = 'Pytest passed'
                    else:
                        # Check for ModuleNotFoundError in output indicating collection failure
                        output = res.stdout + res.stderr
                        if 'ModuleNotFoundError' in output:
                            # If pytest reports collection errors or no tests collected due to import errors, skip
                            if 'error collecting' in output.lower() or 'collected 0 items' in output.lower() or 'no tests ran' in output.lower():
                                tests_status = SKIPPED
                                tests_detail = 'Skipped due to ModuleNotFoundError during collection'
                            else:
                                # Tests ran but failed, or other error
                                tests_status = FAILED
                                tests_detail = 'Pytest failed'
                        else:
                            tests_status = FAILED
                            tests_detail = 'Pytest failed'
                except subprocess.TimeoutExpired:
                    tests_status = FAILED
                    tests_detail = 'Pytest timed out'
                except Exception as e:
                    tests_status = FAILED
                    tests_detail = f'Pytest error: {e}'
            else:
                # Stdlib fallback
                # Run a script that imports each test file and collects/executes tests
                # We need to handle both bare def test_* and unittest.TestCase

                # Create a runner script
                runner_code = '''
import sys
import os
import unittest
import importlib
import traceback
import inspect

test_files = sys.argv[1:]
collected_tests = 0
failed_tests = 0
skipped_tests = 0
module_not_found = False

for tf in test_files:
    try:
        # Convert path to module name
        # Assume cwd is workdir
        rel_path = os.path.relpath(tf, os.getcwd())
        if rel_path.startswith('src/'):
            rel_path = rel_path[4:]
        mod_name = rel_path.replace(os.sep, '.').replace('/', '.').replace('...', '.').replace('.py', '')

        # Import module
        mod = importlib.import_module(mod_name)

        # Collect bare test functions
        for name in dir(mod):
            if name.startswith('test_'):
                func = getattr(mod, name)
                if callable(func) and not isinstance(func, type):
                    try:
                        sig = inspect.signature(func)
                        # Check if all parameters have defaults or are optional
                        # A bare test function should be callable with no arguments
                        has_required_args = False
                        for param in sig.parameters.values():
                            if param.default is inspect.Parameter.empty and param.kind not in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD):
                                has_required_args = True
                                break
                        if not has_required_args:
                            collected_tests += 1
                            try:
                                func()
                            except Exception as e:
                                failed_tests += 1
                                print(f'FAIL: {tf}::{name} - {e}')
                                traceback.print_exc()
                    except (ValueError, TypeError):
                        # If signature inspection fails, assume it might be a test function
                        # and try to call it. If it fails due to args, it's not a valid test.
                        try:
                            func()
                            collected_tests += 1
                        except TypeError:
                            pass
                        except Exception as e:
                            collected_tests += 1
                            failed_tests += 1
                            print(f'FAIL: {tf}::{name} - {e}')
                            traceback.print_exc()

        # Collect unittest.TestCase subclasses
        for name in dir(mod):
            cls = getattr(mod, name)
            if isinstance(cls, type) and issubclass(cls, unittest.TestCase) and cls is not unittest.TestCase:
                suite = unittest.TestLoader().loadTestsFromTestCase(cls)
                for test in suite:
                    collected_tests += 1
                    try:
                        result = test.run()
                        if not result.wasSuccessful():
                            failed_tests += 1
                            print(f'FAIL: {tf}::{test.id()}')
                    except Exception as e:
                        failed_tests += 1
                        print(f'FAIL: {tf}::{test.id()} - {e}')
                        traceback.print_exc()

    except ModuleNotFoundError as e:
        # Check if it's a third-party package
        # If the missing module is not in the bundle, it's third party
        # We don't have the bundle here, but we can assume if it's not a local path, it's third party
        # For simplicity, if we can't import the test file itself, it's a failure unless it's clearly third party
        # But the spec says: 'If 0 tests are collected because of ModuleNotFoundError for an uninstalled third-party package, return SKIPPED'
        # This implies if the test file imports a third-party package that is missing.
        # We can't easily distinguish here without bundle info.
        # However, if the test file itself fails to import due to ModuleNotFoundError, we might skip.
        # Let's assume if the test file import fails with ModuleNotFoundError, it's a skip candidate.
        module_not_found = True
        print(f'SKIP: {tf} - ModuleNotFoundError: {e}')
    except Exception as e:
        failed_tests += 1
        print(f'ERROR: {tf} - {e}')
        traceback.print_exc()

if collected_tests == 0 and module_not_found:
    print('RESULT: SKIPPED')
elif failed_tests > 0:
    print('RESULT: FAILED')
elif collected_tests == 0:
    print('RESULT: FAILED')
else:
    print('RESULT: PASSED')
'''
                try:
                    res = subprocess.run(
                        [self.python_executable, '-c', runner_code] + test_files,
                        cwd=workdir,
                        env=env,
                        capture_output=True,
                        text=True,
                        timeout=self.timeout_s
                    )
                    output = res.stdout + res.stderr
                    if 'RESULT: PASSED' in output:
                        tests_detail = 'Stdlib tests passed'
                    elif 'RESULT: SKIPPED' in output:
                        tests_status = SKIPPED
                        tests_detail = "Skipped due to ModuleNotFoundError"
                    else:
                        tests_status = FAILED
                        tests_detail = "Stdlib tests failed"
                except subprocess.TimeoutExpired:
                    tests_status = FAILED
                    tests_detail = "Stdlib tests timed out"
                except Exception as e:
                    tests_status = FAILED
                    tests_detail = f"Stdlib tests error: {e}"

        gates.append(GateResult(
            name='tests',
            status=tests_status,
            method=tests_method,
            detail=tests_detail,
            duration_s=time.time() - start_time,
            evidence=tests_evidence
        ))

        # 5. Telemetry Gate
        start_time = time.time()
        telemetry_status = FAILED
        telemetry_detail = ''
        telemetry_method = 'ast_analysis'
        telemetry_evidence = {}

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for p in py_files:
            try:
                tree = ast.parse(authored[p])
                for node in ast.walk(tree):
                    # Check for import opentelemetry
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for calls
                    if isinstance(node, ast.Call):
                        func = node.func
                        # Handle method calls like tracer.start_span()
                        if isinstance(func, ast.Attribute):
                            if func.attr in tracer_methods:
                                has_call = True
                        # Handle function calls like get_tracer()
                        elif isinstance(func, ast.Name):
                            if func.id in tracer_methods:
                                has_call = True
            except Exception:
                pass

        if has_import and has_call:
            telemetry_status = PASSED
            telemetry_detail = "Found OpenTelemetry import and tracer/span calls"
        elif has_import:
            telemetry_status = FAILED
            telemetry_detail = "Found OpenTelemetry import but no tracer/span calls"
        else:
            telemetry_status = FAILED
            telemetry_detail = "No OpenTelemetry import found"

        gates.append(GateResult(
            name='telemetry',
            status=telemetry_status,
            method=telemetry_method,
            detail=telemetry_detail,
            duration_s=time.time() - start_time,
            evidence=telemetry_evidence
        ))

        # Calculate Penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )
